 <?php $__env->startSection('title','Pengaduan'); ?> <?php $__env->startSection('content'); ?><?php if(auth()->user()->role==='nasabah'): ?><div class="text-end mb-3"><a class="btn btn-success" href="<?php echo e(route('complaints.create')); ?>">+ Buat Pengaduan</a></div><?php endif; ?><div class="row g-3"><?php $__empty_1 = true; $__currentLoopData = $complaints; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $c): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><div class="col-md-6"><div class="card h-100"><div class="card-body"><h5><?php echo e($c->subject); ?></h5><small><?php echo e($c->customer->name); ?> · <?php echo e($c->created_at->format('d/m/Y H:i')); ?></small><p class="mt-2"><?php echo e($c->message); ?></p><span class="badge bg-secondary"><?php echo e($c->status); ?></span><?php if($c->response): ?><div class="alert alert-light mt-2"><b>Tanggapan:</b> <?php echo e($c->response); ?></div><?php endif; ?> <?php if(in_array(auth()->user()->role,['admin','petugas'])): ?><hr><form method="post" action="<?php echo e(route('complaints.update',$c)); ?>"><?php echo csrf_field(); ?> <?php echo method_field('patch'); ?><select class="form-select mb-2" name="status"><option>processed</option><option>resolved</option><option>closed</option></select><textarea class="form-control mb-2" name="response" placeholder="Tanggapan"></textarea><button class="btn btn-sm btn-success">Update</button></form><?php endif; ?></div></div></div><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><div class="text-muted">Belum ada pengaduan.</div><?php endif; ?></div><div class="mt-3"><?php echo e($complaints->links()); ?></div><?php $__env->stopSection(); ?>
